import {
  GET_MANUFACTURERS,
  GET_MANUFACTURERS_SUCCESS,
  GET_MANUFACTURERS_FAILED,
  CREATE_MANUFACTURER_FAILED,
  CREATE_MANUFACTURER_SUCCESS,
  CREATE_MANUFACTURER,
  UPDATE_MANUFACTURER,
  UPDATE_MANUFACTURER_SUCCESS,
  UPDATE_MANUFACTURER_FAILED,
  RESET_REDUX,
  SEARCH_MANUFACTURERS_SUCCESS,
  SEARCH_MANUFACTURERS_FAILED,
} from "./constants";

const INIT_STATE = {
  loading: false,
  errors: [],
  success: false,
  updated: false,
  manufacturers: [],
  count: 0,
  next: null,
  previous: null,
  message: null,
};

const Manufacturers = (state = INIT_STATE, action) => {
  switch (action.type) {
    case RESET_REDUX:
      return {
        ...state,
        updated: false,
        loading: false,
        success: false,
        message: null,
      };
    case GET_MANUFACTURERS:
      return {
        ...state,
        loading: true,
        errors: null,
        success: false,
        message: null,
      };
    case CREATE_MANUFACTURER:
    case UPDATE_MANUFACTURER:
      return {
        ...state,
        success: false,
        updated: false,
        error: null,
        loading: true,
      };

    case GET_MANUFACTURERS_SUCCESS:
    case SEARCH_MANUFACTURERS_SUCCESS:
      return {
        ...state,
        manufacturers: action.payload.results,
        count: action.payload.count,
        next: action.payload.next,
        previous: action.payload.previous,
        loading: false,
      };
    case CREATE_MANUFACTURER_SUCCESS:
    case UPDATE_MANUFACTURER_SUCCESS:
      return {
        ...state,
        manufacturers: action.payload,
        message: "Body system updated succesfully",
        success: true,
        updated: true,
        loading: false,
      };

    case GET_MANUFACTURERS_FAILED:
    case SEARCH_MANUFACTURERS_FAILED:
      return { ...state, manufacturers: null, loading: false };

    case CREATE_MANUFACTURER_FAILED:
    case UPDATE_MANUFACTURER_FAILED:
      return {
        ...state,
        error: action.payload.message,
        errors: action.payload.errors,
        success: false,
        loading: false,
      };

    default:
      return { ...state };
  }
};

export default Manufacturers;
